module sequence_detector #(
    parameter IDLE = 5'b00001,
    parameter S1   = 5'b00010,
    parameter S2   = 5'b00100,
    parameter S3   = 5'b01000,
    parameter S4   = 5'b10000
) (
    input  clk,
    input  rst_n,
    input  data_in,
    output sequence_detected
);

    reg [2:0] current_state;
    reg [2:0] next_state;

    wire match_s1 = (current_state == 3'b001 && data_in == 1'b0);
    wire match_s2 = (current_state == 3'b010 && data_in == 1'b0);
    wire match_s3 = (current_state == 3'b100 && data_in == 1'b1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= 3'b000; 
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = 3'b000; 
        case (current_state)
            3'b000: 
                if (data_in == 1'b1) begin
                    next_state = 3'b001; 
                end
            3'b001: 
                if (data_in == 1'b0) begin
                    next_state = 3'b010; 
                end
            3'b010: 
                if (data_in == 1'b0) begin
                    next_state = 3'b100; 
                end
            3'b100: 
                if (data_in == 1'b1) begin
                    next_state = 3'b101; 
                end
            3'b101: 
                next_state = 3'b000; 
            default:
                next_state = 3'b000; 
        endcase
    end

    assign sequence_detected = (current_state == 3'b101); 

endmodule
